import React, { useState, useEffect, useRef } from 'react';
import { Canvas, useFrame } from '@react-three/fiber';
import { MeshDistortMaterial, Sphere, Float } from '@react-three/drei';
import { Card, CardContent } from './ui/card';

function SkillOrb({ color, distort }) {
  const ref = useRef();
  useFrame((s) => {
    ref.current.rotation.x = s.clock.getElapsedTime() * 0.4;
    ref.current.rotation.y = s.clock.getElapsedTime() * 0.3;
  });
  return (
    <Float speed={1.5} floatIntensity={0.8}>
      <Sphere ref={ref} args={[1, 64, 64]}>
        <MeshDistortMaterial color={color} distort={distort} speed={3} roughness={0.1} metalness={0.9} transparent opacity={0.65} />
      </Sphere>
    </Float>
  );
}

// Animated counter hook
function useCounter(target, duration = 1500) {
  const [count, setCount] = useState(0);
  const started = useRef(false);
  useEffect(() => {
    if (started.current) return;
    started.current = true;
    const start = performance.now();
    const tick = (now) => {
      const progress = Math.min((now - start) / duration, 1);
      setCount(Math.floor(progress * target));
      if (progress < 1) requestAnimationFrame(tick);
    };
    requestAnimationFrame(tick);
  }, [target, duration]);
  return count;
}

const skillCategories = [
  { title: 'Languages',          icon: '💻', skills: ['Golang', 'Scala', 'Java', 'Python', 'JavaScript', 'TypeScript'], color: 'from-orange-500 to-red-500' },
  { title: 'Backend',            icon: '⚙️', skills: ['Spring Boot', 'Django', 'REST APIs', 'Microservices'],           color: 'from-yellow-500 to-orange-500' },
  { title: 'Frontend',           icon: '🎨', skills: ['React', 'Angular', 'HTML5', 'CSS3'],                             color: 'from-orange-400 to-yellow-400' },
  { title: 'Cloud & DevOps',     icon: '☁️', skills: ['AWS (EC2, EMR, EKS)', 'Azure', 'Docker', 'Kubernetes', 'CI/CD', 'Apache Airflow', 'Apache Flink'], color: 'from-yellow-400 to-orange-400' },
  { title: 'Databases & Storage',icon: '🗄️', skills: ['PostgreSQL', 'MySQL', 'MongoDB', 'Apache Hive', 'Apache Iceberg', 'Apache Trino'], color: 'from-orange-500 to-yellow-500' },
  { title: 'Tools & Practices',  icon: '🛠️', skills: ['Git', 'Agile/Scrum', 'VS Code', 'IntelliJ', 'JIRA', 'Postman'], color: 'from-yellow-500 to-orange-600' },
];

// Tilt card
function TiltCard({ children, className, onEnter, onLeave }) {
  const ref = useRef(null);
  const handleMove = (e) => {
    const rect = ref.current.getBoundingClientRect();
    const x = ((e.clientX - rect.left) / rect.width - 0.5) * 18;
    const y = ((e.clientY - rect.top) / rect.height - 0.5) * -18;
    ref.current.style.transform = `perspective(800px) rotateX(${y}deg) rotateY(${x}deg) scale(1.04)`;
  };
  const handleLeave = () => {
    ref.current.style.transform = 'perspective(800px) rotateX(0deg) rotateY(0deg) scale(1)';
    onLeave?.();
  };
  return (
    <div
      ref={ref}
      className={className}
      onMouseMove={handleMove}
      onMouseEnter={onEnter}
      onMouseLeave={handleLeave}
      style={{ transition: 'transform 0.15s ease-out', transformStyle: 'preserve-3d' }}
    >
      {children}
    </div>
  );
}

const Skills = () => {
  const [hoveredCategory, setHoveredCategory] = useState(null);
  const leetCount = useCounter(500);
  const ytCount = useCounter(160);

  return (
    <section id="skills" className="py-20 relative overflow-hidden">
      <div className="absolute inset-0 bg-gradient-to-b from-black via-gray-950 to-black" />

      {/* 3D orb decoration */}
      <div className="absolute bottom-10 right-10 w-56 h-56 pointer-events-none opacity-50">
        <Canvas camera={{ position: [0, 0, 4], fov: 50 }} gl={{ alpha: true, antialias: true }} dpr={[1, 2]}>
          <ambientLight intensity={0.3} />
          <pointLight position={[3, 3, 3]} intensity={2} color="#ffd700" />
          <SkillOrb color="#ffd700" distort={0.6} />
        </Canvas>
      </div>

      <div className="relative z-10 max-w-6xl mx-auto px-4">
        <div className="text-center mb-16 animate-fade-up">
          <h2 className="text-5xl font-bold mb-6">
            <span className="bg-gradient-to-r from-orange-400 to-yellow-400 bg-clip-text text-transparent">
              Technical Skills
            </span>
          </h2>
          <div className="w-24 h-1 bg-gradient-to-r from-orange-500 to-yellow-500 mx-auto rounded" />
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
          {skillCategories.map((category, index) => (
            <TiltCard
              key={index}
              onEnter={() => setHoveredCategory(index)}
              onLeave={() => setHoveredCategory(null)}
              style={{ animation: `fadeUp 0.6s ease-out forwards`, animationDelay: `${index * 0.1}s`, opacity: 0 }}
            >
              <Card className={`h-full bg-gradient-to-br from-gray-900/80 to-gray-800/80 border-orange-500/30 backdrop-blur-sm transition-all duration-500 ${hoveredCategory === index ? 'glow-orange-strong' : ''}`}>
                <CardContent className="p-6">
                  <div className="text-center mb-6">
                    <div className="text-4xl mb-3">{category.icon}</div>
                    <h3 className="text-2xl font-bold text-white">{category.title}</h3>
                    <div className={`w-16 h-1 bg-gradient-to-r ${category.color} mx-auto mt-2 rounded`} />
                  </div>

                  <div className="space-y-3">
                    {category.skills.map((skill, skillIndex) => (
                      <div key={skillIndex} className="group/skill">
                        <div className="flex justify-between text-sm mb-1">
                          <span className="text-gray-300 group-hover/skill:text-white transition-colors duration-200">{skill}</span>
                          <span style={{ fontFamily: 'monospace', color: hoveredCategory === index ? '#39ff14' : '#00f5ff', opacity: hoveredCategory === index ? 1 : 0.7, fontSize: '0.7rem' }}>
                            {hoveredCategory === index ? 'MAX' : 'LVL 10'}
                          </span>
                        </div>
                        <div className="h-1.5 bg-gray-700 rounded-full overflow-hidden">
                          <div
                            className="h-full rounded-full transition-all duration-700"
                            style={{ width: hoveredCategory === index ? '100%' : '70%', background: 'linear-gradient(90deg, #ff6b35, #ffd700, #00f5ff)' }}
                          />
                        </div>
                      </div>
                    ))}
                  </div>
                </CardContent>
              </Card>
            </TiltCard>
          ))}
        </div>

        {/* Algorithm stats with counter */}
        <div className="mt-16 text-center">
          <TiltCard className="inline-block">
            <Card className="bg-gradient-to-r from-orange-500/10 to-yellow-500/10 border-2 border-orange-500/30 backdrop-blur-sm">
              <CardContent className="p-8">
                <h3 className="text-2xl font-bold text-orange-400 mb-6">Algorithm Expertise</h3>
                <div className="flex flex-col md:flex-row items-center justify-center gap-12">
                  <div className="text-center">
                    <div className="text-6xl font-bold text-yellow-400 mb-2 tabular-nums">{leetCount}+</div>
                    <div className="text-gray-300">LeetCode Problems</div>
                  </div>
                  <div className="text-center">
                    <div className="text-6xl font-bold text-orange-400 mb-2 tabular-nums">{ytCount}+</div>
                    <div className="text-gray-300">YouTube Tutorials</div>
                  </div>
                </div>
                <p className="text-gray-400 mt-6">
                  Published on{' '}
                  <a href="https://www.youtube.com/@AlgorithmArena" target="_blank" rel="noopener noreferrer" className="text-yellow-400 font-semibold hover:text-yellow-300 transition-colors">
                    Algorithm Arena
                  </a>
                </p>
              </CardContent>
            </Card>
          </TiltCard>
        </div>
      </div>
    </section>
  );
};

export default Skills;
