import React, { useState, useRef } from 'react';
import { Canvas, useFrame } from '@react-three/fiber';
import { Torus, MeshWobbleMaterial, Float } from '@react-three/drei';
import { Card, CardContent, CardHeader, CardTitle } from './ui/card';
import { Badge } from './ui/badge';
import { Button } from './ui/button';
import { Award, ExternalLink, Lock } from 'lucide-react';

function SpinningTorus({ color }) {
  const ref = useRef();
  useFrame((s) => {
    ref.current.rotation.x = s.clock.getElapsedTime() * 0.5;
    ref.current.rotation.y = s.clock.getElapsedTime() * 0.7;
  });
  return (
    <Float speed={1.5} floatIntensity={0.5}>
      <Torus ref={ref} args={[0.8, 0.25, 32, 100]}>
        <MeshWobbleMaterial color={color} factor={0.4} speed={2} roughness={0.1} metalness={0.9} transparent opacity={0.7} />
      </Torus>
    </Float>
  );
}

function TiltCard({ children, delay = 0, hovered, onEnter, onLeave }) {
  const ref = useRef(null);
  const handleMove = (e) => {
    const rect = ref.current.getBoundingClientRect();
    const x = ((e.clientX - rect.left) / rect.width - 0.5) * 16;
    const y = ((e.clientY - rect.top) / rect.height - 0.5) * -16;
    ref.current.style.transform = `perspective(800px) rotateX(${y}deg) rotateY(${x}deg) scale(1.04)`;
  };
  const handleLeave = () => {
    ref.current.style.transform = 'perspective(800px) rotateX(0deg) rotateY(0deg) scale(1)';
    onLeave?.();
  };
  return (
    <div
      ref={ref}
      onMouseMove={handleMove}
      onMouseEnter={onEnter}
      onMouseLeave={handleLeave}
      style={{ transition: 'transform 0.15s ease-out', transformStyle: 'preserve-3d', animation: `fadeUp 0.6s ease-out forwards`, animationDelay: `${delay}s`, opacity: 0 }}
    >
      {children}
    </div>
  );
}

