import React, { useRef, useMemo, useState, useEffect, useCallback } from 'react';
import { Canvas, useFrame, useThree } from '@react-three/fiber';
import { Trail, Stars } from '@react-three/drei';
import * as THREE from 'three';

// ─────────────────────────────────────────────
//  CONSTANTS
// ─────────────────────────────────────────────
const BOUNDS = { x: 7, y: 5 };
const LASER_SPEED = 0.45;
const PLAYER_SPEED = 0.12;
const COLORS = { laser: '#00ffff', laserCore: '#ffffff', enemy: '#ff4444', enemyGlow: '#ff0000', boss: '#ff00ff', bossGlow: '#cc00ff', asteroid: '#888888', shield: '#00aaff', explosion: '#ff6b35', explosionB: '#ffd700' };

// ─────────────────────────────────────────────
//  STARFIELD (parallax layers)
// ─────────────────────────────────────────────
function Starfield() {
  const ref = useRef();
  const { positions, speeds } = useMemo(() => {
    const count = 400;
    const positions = new Float32Array(count * 3);
    const speeds = new Float32Array(count);
    for (let i = 0; i < count; i++) {
      positions[i * 3]     = (Math.random() - 0.5) * 20;
      positions[i * 3 + 1] = (Math.random() - 0.5) * 14;
      positions[i * 3 + 2] = (Math.random() - 0.5) * 8 - 4;
      speeds[i] = 0.01 + Math.random() * 0.03;
    }
    return { positions, speeds };
  }, []);

  useFrame(() => {
    const arr = ref.current.geometry.attributes.position.array;
    for (let i = 0; i < 400; i++) {
      arr[i * 3 + 1] -= speeds[i];
      if (arr[i * 3 + 1] < -7) arr[i * 3 + 1] = 7;
    }
    ref.current.geometry.attributes.position.needsUpdate = true;
  });

  return (
    <points ref={ref}>
      <bufferGeometry>
        <bufferAttribute attach="attributes-position" args={[positions, 3]} />
      </bufferGeometry>
      <pointsMaterial size={0.04} color="#aaaaff" transparent opacity={0.7} sizeAttenuation />
    </points>
  );
}

// ─────────────────────────────────────────────
//  ASTEROID
// ─────────────────────────────────────────────
function Asteroid({ initPos, speed, size }) {
  const ref = useRef();
  const pos = useRef(new THREE.Vector3(...initPos));
  const rotSpeed = useRef([(Math.random() - 0.5) * 0.04, (Math.random() - 0.5) * 0.04, (Math.random() - 0.5) * 0.04]);

  useFrame(() => {
    pos.current.y -= speed;
    if (pos.current.y < -6) pos.current.set((Math.random() - 0.5) * 14, 7, (Math.random() - 0.5) * 2 - 3);
    ref.current.position.copy(pos.current);
    ref.current.rotation.x += rotSpeed.current[0];
    ref.current.rotation.y += rotSpeed.current[1];
    ref.current.rotation.z += rotSpeed.current[2];
  });

  return (
    <mesh ref={ref} position={initPos}>
      <dodecahedronGeometry args={[size, 0]} />
      <meshStandardMaterial color={COLORS.asteroid} roughness={0.9} metalness={0.1} />
    </mesh>
  );
}

// ─────────────────────────────────────────────
//  PLAYER SHIP
// ─────────────────────────────────────────────
function PlayerShip({ playerPos, shieldPct }) {
  const ref = useRef();
  const shieldRef = useRef();
  const engineRef = useRef();
  const t0 = useRef(0);

  useFrame((state) => {
    const t = state.clock.getElapsedTime();
    ref.current.position.set(playerPos.current.x, playerPos.current.y, 0);
    // tilt on horizontal movement
    ref.current.rotation.z = -playerPos.current.vx * 0.4;
    ref.current.rotation.x = 0.2;

    // engine glow pulse
    if (engineRef.current) {
      engineRef.current.intensity = 1.5 + Math.sin(t * 12) * 0.5;
    }
    // shield pulse
    if (shieldRef.current) {
      shieldRef.current.material.opacity = (shieldPct.current > 0 ? 0.15 : 0) + Math.sin(t * 4) * 0.04;
    }
  });

  return (
    <group ref={ref}>
      {/* fuselage */}
      <mesh>
        <coneGeometry args={[0.18, 0.7, 6]} />
        <meshStandardMaterial color="#00ccff" emissive="#0066aa" emissiveIntensity={0.6} metalness={1} roughness={0.1} />
      </mesh>
      {/* left wing */}
      <mesh position={[-0.35, -0.25, 0]} rotation={[0, 0, 0.5]}>
        <coneGeometry args={[0.08, 0.5, 4]} />
        <meshStandardMaterial color="#0088cc" emissive="#004466" emissiveIntensity={0.4} metalness={1} roughness={0.1} />
      </mesh>
      {/* right wing */}
      <mesh position={[0.35, -0.25, 0]} rotation={[0, 0, -0.5]}>
        <coneGeometry args={[0.08, 0.5, 4]} />
        <meshStandardMaterial color="#0088cc" emissive="#004466" emissiveIntensity={0.4} metalness={1} roughness={0.1} />
      </mesh>
      {/* engine light */}
      <pointLight ref={engineRef} position={[0, -0.4, 0]} color="#00ffff" intensity={1.5} distance={3} />
      {/* engine exhaust */}
      <mesh position={[0, -0.45, 0]}>
        <sphereGeometry args={[0.1, 8, 8]} />
        <meshBasicMaterial color="#00ffff" transparent opacity={0.8} />
      </mesh>
      {/* shield bubble */}
      <mesh ref={shieldRef}>
        <sphereGeometry args={[0.7, 16, 16]} />
        <meshBasicMaterial color={COLORS.shield} transparent opacity={0.15} side={THREE.DoubleSide} />
      </mesh>
    </group>
  );
}

// ─────────────────────────────────────────────
//  LASER
// ─────────────────────────────────────────────
function Laser({ laser }) {
  const ref = useRef();
  useFrame(() => {
    if (!laser.active) return;
    laser.y += LASER_SPEED;
    ref.current.position.set(laser.x, laser.y, 0);
    if (laser.y > BOUNDS.y + 1) laser.active = false;
  });
  if (!laser.active) return null;
  return (
    <Trail width={0.15} length={5} color={COLORS.laser} attenuation={t => t * t}>
      <mesh ref={ref} position={[laser.x, laser.y, 0]}>
        <capsuleGeometry args={[0.04, 0.3, 4, 8]} />
        <meshBasicMaterial color={COLORS.laserCore} />
      </mesh>
    </Trail>
  );
}

// ─────────────────────────────────────────────
//  EXPLOSION RING
// ─────────────────────────────────────────────
function ExplosionRing({ x, y, onDone }) {
  const ref = useRef();
  const born = useRef(null);

  useFrame((state) => {
    if (born.current === null) born.current = state.clock.getElapsedTime();
    const age = state.clock.getElapsedTime() - born.current;
    const s = 1 + age * 6;
    ref.current.scale.setScalar(s);
    ref.current.material.opacity = Math.max(0, 1 - age * 3);
    if (age > 0.5) onDone();
  });

  return (
    <mesh ref={ref} position={[x, y, 0]}>
      <torusGeometry args={[0.3, 0.06, 8, 24]} />
      <meshBasicMaterial color={COLORS.explosion} transparent opacity={1} />
    </mesh>
  );
}

// ─────────────────────────────────────────────
//  EXPLOSION SPARKS
// ─────────────────────────────────────────────
function ExplosionSparks({ x, y, onDone }) {
  const ref = useRef();
  const born = useRef(null);
  const { positions, velocities } = useMemo(() => {
    const n = 20;
    const positions = new Float32Array(n * 3);
    const velocities = [];
    for (let i = 0; i < n; i++) {
      positions[i * 3] = x; positions[i * 3 + 1] = y; positions[i * 3 + 2] = 0;
      const a = (i / n) * Math.PI * 2;
      const sp = 0.04 + Math.random() * 0.08;
      velocities.push([Math.cos(a) * sp, Math.sin(a) * sp, (Math.random() - 0.5) * 0.04]);
    }
    return { positions, velocities };
  }, [x, y]);

  useFrame((state) => {
    if (!ref.current) return;
    if (born.current === null) born.current = state.clock.getElapsedTime();
    const age = state.clock.getElapsedTime() - born.current;
    const arr = ref.current.geometry.attributes.position.array;
    for (let i = 0; i < 20; i++) {
      arr[i * 3]     += velocities[i][0];
      arr[i * 3 + 1] += velocities[i][1];
      arr[i * 3 + 2] += velocities[i][2];
    }
    ref.current.geometry.attributes.position.needsUpdate = true;
    ref.current.material.opacity = Math.max(0, 1 - age * 2.5);
    if (age > 0.6) onDone();
  });

  return (
    <points ref={ref}>
      <bufferGeometry>
        <bufferAttribute attach="attributes-position" args={[positions, 3]} />
      </bufferGeometry>
      <pointsMaterial size={0.1} color={COLORS.explosionB} transparent opacity={1} sizeAttenuation />
    </points>
  );
}

// ─────────────────────────────────────────────
//  ENEMY
// ─────────────────────────────────────────────
function Enemy({ enemy, lasers, onKill, onEscape }) {
  const ref = useRef();
  const alive = useRef(true);
  const hp = useRef(enemy.hp);

  useFrame((state) => {
    if (!alive.current) return;
    const t = state.clock.getElapsedTime();

    // movement pattern
    enemy.y -= enemy.speed;
    if (enemy.pattern === 'zigzag') enemy.x += Math.sin(t * 3 + enemy.phase) * 0.04;
    if (enemy.pattern === 'spiral') {
      enemy.x += Math.cos(t * 2 + enemy.phase) * 0.03;
      enemy.y -= Math.sin(t * 1.5 + enemy.phase) * 0.01;
    }
    ref.current.position.set(enemy.x, enemy.y, 0);
    ref.current.rotation.x = t * 1.5;
    ref.current.rotation.y = t * enemy.speed * 10;

    if (enemy.y < -BOUNDS.y - 1) { alive.current = false; onEscape(enemy.id); return; }

    // laser collision
    for (const l of lasers.current) {
      if (!l.active) continue;
      const dx = l.x - enemy.x, dy = l.y - enemy.y;
      if (Math.sqrt(dx * dx + dy * dy) < enemy.radius) {
        l.active = false;
        hp.current -= 1;
        if (hp.current <= 0) {
          alive.current = false;
          onKill(enemy.id, enemy.x, enemy.y, enemy.score);
        }
        return;
      }
    }
  });

  if (!alive.current) return null;

  const isBoss = enemy.type === 'boss';
  return (
    <mesh ref={ref} position={[enemy.x, enemy.y, 0]}>
      {isBoss
        ? <torusKnotGeometry args={[0.5, 0.18, 64, 8]} />
        : enemy.type === 'cruiser'
          ? <octahedronGeometry args={[0.35, 0]} />
          : <tetrahedronGeometry args={[0.28, 0]} />
      }
      <meshStandardMaterial
        color={isBoss ? COLORS.boss : COLORS.enemy}
        emissive={isBoss ? COLORS.bossGlow : COLORS.enemyGlow}
        emissiveIntensity={isBoss ? 1.2 : 0.6}
        metalness={0.8}
        roughness={0.1}
      />
    </mesh>
  );
}

// ─────────────────────────────────────────────
//  GAME ENGINE (inner canvas component)
// ─────────────────────────────────────────────
function GameEngine({ gameState, onScore, onLoseLife, onWaveComplete, onGameOver }) {
  const { gl, camera } = useThree();
  const keys = useRef({});
  const lasers = useRef([]);
  const lastShot = useRef(0);
  const playerPos = useRef({ x: 0, y: -3.5, vx: 0, vy: 0 });
  const shieldPct = useRef(1);
  const shieldCooldown = useRef(0);
  const [enemies, setEnemies] = useState([]);
  const [explosions, setExplosions] = useState([]);
  const waveRef = useRef(gameState.wave);
  const aliveRef = useRef(true);
  const spawnedWave = useRef(-1);

  // spawn wave
  useEffect(() => {
    if (gameState.status !== 'playing') return;
    if (spawnedWave.current === gameState.wave) return;
    spawnedWave.current = gameState.wave;
    waveRef.current = gameState.wave;
    const wave = gameState.wave;
    const isBossWave = wave % 5 === 0;
    const newEnemies = [];

    if (isBossWave) {
      newEnemies.push({ id: Math.random(), type: 'boss', x: 0, y: BOUNDS.y + 1, speed: 0.012 + wave * 0.001, pattern: 'zigzag', phase: 0, hp: 8 + wave, radius: 0.7, score: 500 * wave });
    } else {
      const count = 4 + wave * 2;
      for (let i = 0; i < count; i++) {
        const type = i % 3 === 0 ? 'cruiser' : 'scout';
        const col = count <= 8 ? i : i % 8;
        newEnemies.push({
          id: Math.random(),
          type,
          x: -3.5 + (col / Math.min(count - 1, 7)) * 7,
          y: BOUNDS.y + 1 + Math.floor(i / 8) * 1.2,
          speed: (type === 'scout' ? 0.018 : 0.012) + wave * 0.002,
          pattern: type === 'scout' ? 'zigzag' : 'straight',
          phase: Math.random() * Math.PI * 2,
          hp: type === 'cruiser' ? 2 : 1,
          radius: type === 'cruiser' ? 0.45 : 0.35,
          score: type === 'cruiser' ? 200 : 100,
        });
      }
    }
    setEnemies(newEnemies);
  }, [gameState.wave, gameState.status]);

  // keyboard
  useEffect(() => {
    const down = e => { keys.current[e.key] = true; };
    const up   = e => { keys.current[e.key] = false; };
    window.addEventListener('keydown', down);
    window.addEventListener('keyup', up);
    return () => { window.removeEventListener('keydown', down); window.removeEventListener('keyup', up); };
  }, []);

  const handleKill = useCallback((id, x, y, score) => {
    onScore(score);
    const eid = Math.random();
    const eid2 = Math.random();
    setExplosions(prev => [...prev, { id: eid, type: 'ring', x, y }, { id: eid2, type: 'sparks', x, y }]);
    setEnemies(prev => {
      const next = prev.filter(e => e.id !== id);
      if (next.length === 0) setTimeout(() => onWaveComplete(), 800);
      return next;
    });
  }, [onScore, onWaveComplete]);

  const handleEscape = useCallback((id) => {
    setEnemies(prev => {
      const next = prev.filter(e => e.id !== id);
      if (next.length === 0) setTimeout(() => onWaveComplete(), 800);
      return next;
    });
    if (shieldPct.current > 0) {
      shieldPct.current = Math.max(0, shieldPct.current - 0.34);
    } else {
      onLoseLife();
    }
  }, [onLoseLife]);

  const removeExplosion = useCallback((id) => {
    setExplosions(prev => prev.filter(e => e.id !== id));
  }, []);

  useFrame((state) => {
    if (gameState.status !== 'playing') return;
    const t = state.clock.getElapsedTime();
    const p = playerPos.current;

    // movement
    const left  = keys.current['ArrowLeft']  || keys.current['a'] || keys.current['A'];
    const right = keys.current['ArrowRight'] || keys.current['d'] || keys.current['D'];
    const up    = keys.current['ArrowUp']    || keys.current['w'] || keys.current['W'];
    const down  = keys.current['ArrowDown']  || keys.current['s'] || keys.current['S'];

    p.vx = left ? -PLAYER_SPEED : right ? PLAYER_SPEED : p.vx * 0.8;
    p.vy = up   ? PLAYER_SPEED  : down  ? -PLAYER_SPEED : p.vy * 0.8;
    p.x = Math.max(-BOUNDS.x + 0.5, Math.min(BOUNDS.x - 0.5, p.x + p.vx));
    p.y = Math.max(-BOUNDS.y + 0.3, Math.min(BOUNDS.y - 0.5, p.y + p.vy));

    // auto fire
    if (t - lastShot.current > 0.12) {
      lastShot.current = t;
      lasers.current.push({ x: p.x - 0.15, y: p.y + 0.4, active: true });
      lasers.current.push({ x: p.x + 0.15, y: p.y + 0.4, active: true });
      if (lasers.current.length > 60) lasers.current = lasers.current.filter(l => l.active);
    }

    // shield regen
    if (shieldCooldown.current > 0) shieldCooldown.current -= 0.016;
    else shieldPct.current = Math.min(1, shieldPct.current + 0.001);
  });

  const asteroids = useMemo(() =>
    Array.from({ length: 12 }, (_, i) => ({
      id: i,
      initPos: [(Math.random() - 0.5) * 16, (Math.random() - 0.5) * 12, (Math.random() - 0.5) * 3 - 4],
      speed: 0.008 + Math.random() * 0.015,
      size: 0.1 + Math.random() * 0.25,
    })), []);

  return (
    <>
      <Starfield />
      {asteroids.map(a => <Asteroid key={a.id} {...a} />)}
      <PlayerShip playerPos={playerPos} shieldPct={shieldPct} />
      {lasers.current.map((l, i) => <Laser key={i} laser={l} />)}
      {enemies.map(e => (
        <Enemy key={e.id} enemy={e} lasers={lasers} onKill={handleKill} onEscape={handleEscape} />
      ))}
      {explosions.map(ex =>
        ex.type === 'ring'
          ? <ExplosionRing key={ex.id} x={ex.x} y={ex.y} onDone={() => removeExplosion(ex.id)} />
          : <ExplosionSparks key={ex.id} x={ex.x} y={ex.y} onDone={() => removeExplosion(ex.id)} />
      )}
      {/* ambient lights */}
      <ambientLight intensity={0.2} />
      <pointLight position={[0, 0, 5]} color="#0033ff" intensity={0.5} />
      <pointLight position={[0, 4, 3]} color="#ff3300" intensity={0.3} />
    </>
  );
}

// ─────────────────────────────────────────────
//  MAIN EXPORT
// ─────────────────────────────────────────────
const Scene3D = ({ style, onScoreUpdate, onCombo, onWave, onLives }) => {
  const [gameState, setGameState] = useState({ status: 'playing', wave: 1, score: 0, lives: 3 });
  const hiScore = useRef(parseInt(localStorage.getItem('pg_hiscore') || '0'));

  const handleScore = useCallback((pts) => {
    setGameState(prev => {
      const next = { ...prev, score: prev.score + pts };
      if (next.score > hiScore.current) {
        hiScore.current = next.score;
        localStorage.setItem('pg_hiscore', String(next.score));
      }
      onScoreUpdate?.(next.score, hiScore.current);
      return next;
    });
  }, [onScoreUpdate]);

  const handleLoseLife = useCallback(() => {
    setGameState(prev => {
      const lives = prev.lives - 1;
      onLives?.(lives);
      if (lives <= 0) return { ...prev, lives: 0, status: 'gameover' };
      return { ...prev, lives };
    });
  }, [onLives]);

  const handleWaveComplete = useCallback(() => {
    setGameState(prev => {
      const wave = prev.wave + 1;
      onWave?.(wave);
      return { ...prev, wave, status: 'playing' };
    });
  }, [onWave]);

  const restart = useCallback(() => {
    setGameState({ status: 'playing', wave: 1, score: 0, lives: 3 });
    onLives?.(3);
    onScoreUpdate?.(0, hiScore.current);
    onWave?.(1);
  }, [onLives, onScoreUpdate, onWave]);

  // pass state up for HUD
  useEffect(() => { onLives?.(gameState.lives); }, []);
  useEffect(() => { onWave?.(gameState.wave); }, [gameState.wave]);

  return (
    <div style={{ position: 'absolute', inset: 0, cursor: 'none', ...style }}>
      <Canvas
        camera={{ position: [0, 0, 9], fov: 55 }}
        gl={{ antialias: true, alpha: true }}
        dpr={[1, 1.5]}
      >
        <Stars radius={100} depth={60} count={1000} factor={2} saturation={0} fade speed={0.3} />
        <GameEngine
          gameState={gameState}
          onScore={handleScore}
          onLoseLife={handleLoseLife}
          onWaveComplete={handleWaveComplete}
          onGameOver={() => setGameState(p => ({ ...p, status: 'gameover' }))}
        />
      </Canvas>

      {/* GAME OVER overlay — rendered in DOM over canvas */}
      {gameState.status === 'gameover' && (
        <div style={{
          position: 'absolute', inset: 0, display: 'flex', flexDirection: 'column',
          alignItems: 'center', justifyContent: 'center', background: 'rgba(0,0,0,0.75)',
          zIndex: 10,
        }}>
          <div style={{ fontFamily: 'monospace', color: '#ff4444', fontSize: '3rem', fontWeight: 900, textShadow: '0 0 30px #ff0000', letterSpacing: '0.2em' }}>
            GAME OVER
          </div>
          <div style={{ fontFamily: 'monospace', color: '#ffd700', fontSize: '1.2rem', margin: '12px 0 4px', textShadow: '0 0 10px #ffd700' }}>
            SCORE: {String(gameState.score).padStart(6, '0')}
          </div>
          <div style={{ fontFamily: 'monospace', color: '#ff6b35', fontSize: '0.9rem', marginBottom: '28px' }}>
            HI-SCORE: {String(hiScore.current).padStart(6, '0')}
          </div>
          <button
            onClick={restart}
            style={{
              fontFamily: 'monospace', fontSize: '1rem', fontWeight: 700,
              padding: '10px 32px', background: 'transparent',
              border: '2px solid #00ffff', color: '#00ffff',
              cursor: 'pointer', letterSpacing: '0.15em',
              textShadow: '0 0 10px #00ffff', boxShadow: '0 0 20px rgba(0,255,255,0.3)',
              transition: 'all 0.2s',
            }}
            onMouseEnter={e => { e.target.style.background = 'rgba(0,255,255,0.15)'; }}
            onMouseLeave={e => { e.target.style.background = 'transparent'; }}
          >
            ▶ PLAY AGAIN
          </button>
        </div>
      )}
    </div>
  );
};

export default Scene3D;
