import React, { useRef, useMemo } from 'react';
import { Canvas, useFrame } from '@react-three/fiber';
import * as THREE from 'three';

const DOT_POSITIONS = Array.from({ length: 20 }, (_, i) => ({
  top:      ((i * 37 + 13) % 97),
  left:     ((i * 53 + 7)  % 97),
  delay:    (i * 0.3) % 3,
  duration: 5 + (i % 5),
  color:    i % 2 === 0 ? '#ff6b35' : '#ffd700',
}));

// Drifting particle cloud — very lightweight, runs behind all sections
function DriftingParticles({ count = 120 }) {
  const meshRef = useRef();

  const [positions, colors] = useMemo(() => {
    const pos = new Float32Array(count * 3);
    const col = new Float32Array(count * 3);
    const orange = new THREE.Color('#ff6b35');
    const yellow = new THREE.Color('#ffd700');
    for (let i = 0; i < count; i++) {
      pos[i * 3]     = (Math.random() - 0.5) * 30;
      pos[i * 3 + 1] = (Math.random() - 0.5) * 30;
      pos[i * 3 + 2] = (Math.random() - 0.5) * 10;
      const c = i % 2 === 0 ? orange : yellow;
      col[i * 3] = c.r; col[i * 3 + 1] = c.g; col[i * 3 + 2] = c.b;
    }
    return [pos, col];
  }, [count]);

  useFrame((state) => {
    meshRef.current.rotation.y = state.clock.getElapsedTime() * 0.015;
    meshRef.current.rotation.x = state.clock.getElapsedTime() * 0.005;
  });

  return (
    <points ref={meshRef}>
      <bufferGeometry>
        <bufferAttribute attach="attributes-position" args={[positions, 3]} />
        <bufferAttribute attach="attributes-color" args={[colors, 3]} />
      </bufferGeometry>
      <pointsMaterial size={0.06} vertexColors transparent opacity={0.35} sizeAttenuation />
    </points>
  );
}

const FloatingShapes = () => (
  <div className="fixed inset-0 pointer-events-none z-0">
    <Canvas
      camera={{ position: [0, 0, 10], fov: 75 }}
      gl={{ antialias: false, alpha: true }}
      dpr={1}
    >
      <DriftingParticles count={150} />
    </Canvas>
  </div>
);

export default FloatingShapes;
