import React, { useRef, useState } from 'react';
import { Canvas, useFrame } from '@react-three/fiber';
import { Sphere, MeshDistortMaterial, Float } from '@react-three/drei';
import { Card, CardContent } from './ui/card';
import { Button } from './ui/button';
import { Mail, Github, Linkedin, Youtube, MapPin } from 'lucide-react';

function PulseOrb() {
  const ref = useRef();
  useFrame((s) => {
    const scale = 1 + Math.sin(s.clock.getElapsedTime() * 2) * 0.1;
    ref.current.scale.setScalar(scale);
    ref.current.rotation.y = s.clock.getElapsedTime() * 0.3;
  });
  return (
    <Float speed={1.5} floatIntensity={0.5}>
      <Sphere ref={ref} args={[1, 64, 64]}>
        <MeshDistortMaterial color="#ff6b35" distort={0.4} speed={3} roughness={0.1} metalness={0.8} transparent opacity={0.6} />
      </Sphere>
    </Float>
  );
}

function TiltCard({ children, className }) {
  const ref = useRef(null);
  const handleMove = (e) => {
    const rect = ref.current.getBoundingClientRect();
    const x = ((e.clientX - rect.left) / rect.width - 0.5) * 14;
    const y = ((e.clientY - rect.top) / rect.height - 0.5) * -14;
    ref.current.style.transform = `perspective(800px) rotateX(${y}deg) rotateY(${x}deg) scale(1.02)`;
  };
  const handleLeave = () => {
    ref.current.style.transform = 'perspective(800px) rotateX(0deg) rotateY(0deg) scale(1)';
  };
  return (
    <div ref={ref} onMouseMove={handleMove} onMouseLeave={handleLeave} className={className}
      style={{ transition: 'transform 0.15s ease-out', transformStyle: 'preserve-3d' }}>
      {children}
    </div>
  );
}

