import React, { useRef, useState } from 'react';
import { Canvas, useFrame } from '@react-three/fiber';
import { MeshDistortMaterial, Sphere, Float } from '@react-three/drei';
import { Card, CardContent } from './ui/card';
import { Code, Database, Cloud, Cpu } from 'lucide-react';

function AboutOrb({ color, position, distort }) {
  const ref = useRef();
  useFrame((state) => {
    ref.current.rotation.x = state.clock.getElapsedTime() * 0.3;
    ref.current.rotation.y = state.clock.getElapsedTime() * 0.2;
  });
  return (
    <Float speed={2} floatIntensity={1}>
      <Sphere ref={ref} args={[1, 64, 64]} position={position}>
        <MeshDistortMaterial color={color} distort={distort} speed={3} roughness={0.1} metalness={0.8} transparent opacity={0.6} />
      </Sphere>
    </Float>
  );
}

// Tilt card on mouse move
function TiltCard({ children, className }) {
  const cardRef = useRef(null);
  const handleMove = (e) => {
    const rect = cardRef.current.getBoundingClientRect();
    const x = ((e.clientX - rect.left) / rect.width - 0.5) * 20;
    const y = ((e.clientY - rect.top) / rect.height - 0.5) * -20;
    cardRef.current.style.transform = `perspective(800px) rotateX(${y}deg) rotateY(${x}deg) scale(1.03)`;
  };
  const handleLeave = () => {
    cardRef.current.style.transform = 'perspective(800px) rotateX(0deg) rotateY(0deg) scale(1)';
  };
  return (
    <div
      ref={cardRef}
      onMouseMove={handleMove}
      onMouseLeave={handleLeave}
      className={className}
      style={{ transition: 'transform 0.15s ease-out', transformStyle: 'preserve-3d' }}
    >
      {children}
    </div>
  );
}

const highlights = [
  { icon: Code,     title: 'Backend Development', description: 'Expert in Golang, Scala, Java with microservices architecture' },
  { icon: Database, title: 'Data Engineering',    description: 'Experience with Apache Hive, Iceberg, Trino for big data processing' },
  { icon: Cloud,    title: 'Cloud Architecture',  description: 'AWS EC2, EMR, EKS deployment with Docker and Kubernetes' },
  { icon: Cpu,      title: 'Algorithm Expert',    description: '500+ LeetCode problems solved, YouTube educator with 160+ tutorials' },
];

const bioCards = [
  { border: 'border-orange-500/20', glow: 'glow-orange', text: <>Software Developer with <span className="text-orange-400 font-semibold">1.5+ years</span> of hands-on experience building scalable backend systems using modern technologies and cloud architectures.</> },
  { border: 'border-yellow-500/20', glow: 'glow-gold',   text: 'Specialized in optimizing critical workflows, migrating legacy services, and delivering production-ready microservices. Strong foundation in data structures and algorithms.' },
  { border: 'border-orange-500/20', glow: 'glow-orange', text: <>YouTube educator with <span className="text-orange-400 font-semibold">160+</span> algorithm tutorials published on <span className="text-yellow-400 font-semibold"><a href="https://www.youtube.com/@AlgorithmArena" target="_blank" rel="noopener noreferrer">Algorithm Arena</a></span>, helping others learn DSA.</> },
];

const About = () => {
  const [hoveredCard, setHoveredCard] = useState(null);

  return (
    <section id="about" className="py-20 relative overflow-hidden">
      <div className="absolute inset-0 bg-gradient-to-b from-black via-gray-950 to-black" />

      {/* Mini 3D orb scene — top right decoration */}
      <div className="absolute top-0 right-0 w-80 h-80 pointer-events-none opacity-60">
        <Canvas camera={{ position: [0, 0, 4], fov: 50 }} gl={{ alpha: true, antialias: true }} dpr={[1, 2]}>
          <ambientLight intensity={0.4} />
          <pointLight position={[3, 3, 3]} intensity={2} color="#ff6b35" />
          <AboutOrb color="#ff6b35" position={[0, 0, 0]} distort={0.5} />
        </Canvas>
      </div>

      <div className="relative z-10 max-w-6xl mx-auto px-4">
        <div className="text-center mb-16 animate-fade-up">
          <h2 className="text-5xl font-bold mb-6">
            <span className="bg-gradient-to-r from-orange-400 to-yellow-400 bg-clip-text text-transparent">
              About Me
            </span>
          </h2>
          <div className="w-24 h-1 bg-gradient-to-r from-orange-500 to-yellow-500 mx-auto rounded" />
        </div>

        <div className="grid md:grid-cols-2 gap-12 items-center mb-16">
          {/* Bio cards */}
          <div className="space-y-6">
            {bioCards.map((card, i) => (
              <TiltCard key={i}>
                <Card
                  className={`bg-gray-900/50 ${card.border} backdrop-blur-sm ${card.glow}`}
                  style={{ animation: `fadeUp 0.6s ease-out forwards`, animationDelay: `${i * 0.15}s`, opacity: 0 }}
                >
                  <CardContent className="p-8">
                    <p className="text-lg text-gray-300 leading-relaxed">{card.text}</p>
                  </CardContent>
                </Card>
              </TiltCard>
            ))}
          </div>

          {/* Highlight cards */}
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
            {highlights.map((item, index) => (
              <TiltCard key={index}>
                <Card
                  className={`bg-gradient-to-br from-gray-900/80 to-gray-800/80 border-orange-500/30 backdrop-blur-sm h-full transition-all duration-300 ${hoveredCard === index ? 'glow-orange-strong' : ''}`}
                  style={{ animation: `fadeUp 0.6s ease-out forwards`, animationDelay: `${0.45 + index * 0.1}s`, opacity: 0 }}
                  onMouseEnter={() => setHoveredCard(index)}
                  onMouseLeave={() => setHoveredCard(null)}
                >
                  <CardContent className="p-6 text-center">
                    <div className="mb-4 flex justify-center">
                      <div className="gradient-border inline-block">
                        <div className="p-3 rounded-full bg-gray-900 m-0.5">
                          <item.icon size={28} className="text-orange-400" />
                        </div>
                      </div>
                    </div>
                    <h3 className="text-xl font-semibold text-white mb-3">{item.title}</h3>
                    <p className="text-gray-400 text-sm leading-relaxed">{item.description}</p>
                  </CardContent>
                </Card>
              </TiltCard>
            ))}
          </div>
        </div>
      </div>
    </section>
  );
};

export default About;
