import React, { useEffect, useRef, useState, useCallback } from 'react';
import { Github, Linkedin, Youtube, ChevronDown } from 'lucide-react';
import { Button } from './ui/button';
import LeetCodeSolvedCount from './LeetCodeSolved';
import Scene3D from './Scene3D';

const FULL_NAME = 'Parikshith';

const Hero = () => {
  const sectionRef = useRef(null);
  const [typedName, setTypedName] = useState('');
  const [showG, setShowG] = useState(false);
  const [typingDone, setTypingDone] = useState(false);

  // game state for HUD
  const [score, setScore] = useState(0);
  const [hiScore, setHiScore] = useState(parseInt(localStorage.getItem('pg_hiscore') || '0'));
  const [lives, setLives] = useState(3);
  const [wave, setWave] = useState(1);
  const [waveFlash, setWaveFlash] = useState(false);
  const waveFlashTimer = useRef(null);

  // Typewriter
  useEffect(() => {
    let i = 0;
    const interval = setInterval(() => {
      if (i < FULL_NAME.length) { setTypedName(FULL_NAME.slice(0, i + 1)); i++; }
      else { clearInterval(interval); setTimeout(() => { setShowG(true); setTypingDone(true); }, 300); }
    }, 50);
    return () => clearInterval(interval);
  }, []);

  const handleScore = useCallback((s, hi) => {
    setScore(s);
    setHiScore(hi);
  }, []);

  const handleLives = useCallback((l) => setLives(l), []);

  const handleWave = useCallback((w) => {
    setWave(w);
    setWaveFlash(true);
    clearTimeout(waveFlashTimer.current);
    waveFlashTimer.current = setTimeout(() => setWaveFlash(false), 2000);
  }, []);

  const isBossWave = wave % 5 === 0;

  return (
    <section
      id="hero"
      ref={sectionRef}
      className="min-h-screen flex items-center justify-center relative overflow-hidden"
      style={{ background: '#000008' }}
    >
      {/* Animated grid background */}
      <div className="absolute inset-0 opacity-5 pointer-events-none" style={{
        backgroundImage: 'linear-gradient(#ff6b35 1px, transparent 1px), linear-gradient(90deg, #ff6b35 1px, transparent 1px)',
        backgroundSize: '60px 60px',
      }} />

      {/* Radial glow behind name area */}
      <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-96 h-96 rounded-full opacity-10 pointer-events-none" style={{
        background: 'radial-gradient(circle, #ff6b35 0%, transparent 70%)',
      }} />

      {/* Three.js game canvas */}
      <Scene3D
        style={{ zIndex: 0 }}
        onScoreUpdate={handleScore}
        onLives={handleLives}
        onWave={handleWave}
      />

      {/* scanline overlay */}
      <div className="absolute inset-0 pointer-events-none z-[2]" style={{
        backgroundImage: 'repeating-linear-gradient(0deg, transparent, transparent 2px, rgba(0,0,0,0.08) 2px, rgba(0,0,0,0.08) 4px)',
      }} />

      {/* vignette */}
      <div className="absolute inset-0 pointer-events-none z-[2]" style={{
        background: 'radial-gradient(ellipse at center, transparent 50%, rgba(0,0,10,0.7) 100%)',
      }} />

      {/* ── TOP HUD BAR ── */}
      <div className="absolute top-0 left-0 right-0 z-20 pointer-events-none select-none flex items-stretch" style={{
        background: 'linear-gradient(180deg, rgba(0,0,20,0.95) 0%, rgba(0,0,20,0.7) 100%)',
        borderBottom: '1px solid rgba(0,255,255,0.15)',
        padding: '8px 20px',
      }}>
        {/* score */}
        <div className="flex flex-col min-w-[120px]">
          <span style={{ fontFamily: 'monospace', fontSize: '0.6rem', color: 'rgba(0,255,255,0.5)', letterSpacing: '0.2em' }}>SCORE</span>
          <span style={{ fontFamily: 'monospace', fontSize: '1.4rem', fontWeight: 900, color: '#00ffff', textShadow: '0 0 12px #00ffff', letterSpacing: '0.1em' }}>
            {String(score).padStart(6, '0')}
          </span>
        </div>

        {/* hi-score center */}
        <div className="flex flex-col items-center flex-1">
          <span style={{ fontFamily: 'monospace', fontSize: '0.6rem', color: 'rgba(255,215,0,0.5)', letterSpacing: '0.2em' }}>HI-SCORE</span>
          <span style={{ fontFamily: 'monospace', fontSize: '1.4rem', fontWeight: 900, color: '#ffd700', textShadow: '0 0 12px #ffd700', letterSpacing: '0.1em' }}>
            {String(hiScore).padStart(6, '0')}
          </span>
        </div>

        {/* wave + lives right */}
        <div className="flex flex-col items-end min-w-[120px]">
          <span style={{ fontFamily: 'monospace', fontSize: '0.6rem', color: isBossWave ? 'rgba(255,0,255,0.7)' : 'rgba(255,107,53,0.5)', letterSpacing: '0.2em' }}>
            {isBossWave ? '⚠ BOSS WAVE' : `WAVE ${wave}`}
          </span>
          <div className="flex gap-1 mt-1">
            {Array.from({ length: 3 }).map((_, i) => (
              <span key={i} style={{ fontSize: '1rem', filter: i < lives ? 'drop-shadow(0 0 4px #ff4444)' : 'none', opacity: i < lives ? 1 : 0.2 }}>❤️</span>
            ))}
          </div>
        </div>
      </div>

      {/* ── WAVE FLASH ── */}
      {waveFlash && (
        <div className="absolute inset-0 flex items-center justify-center z-20 pointer-events-none select-none" style={{ animation: 'waveFlashAnim 2s ease-out forwards' }}>
          <div style={{
            fontFamily: 'monospace',
            fontSize: '2.5rem',
            fontWeight: 900,
            letterSpacing: '0.3em',
            color: isBossWave ? '#ff00ff' : '#ffd700',
            textShadow: isBossWave ? '0 0 40px #ff00ff, 0 0 80px #cc00ff' : '0 0 40px #ffd700, 0 0 80px #ff6b35',
          }}>
            {isBossWave ? '⚠ BOSS INCOMING ⚠' : `WAVE ${wave}`}
          </div>
        </div>
      )}

      {/* ── CONTROLS HINT (bottom left) ── */}
      <div className="absolute bottom-20 left-4 z-20 pointer-events-none select-none" style={{
        fontFamily: 'monospace', fontSize: '0.65rem', color: 'rgba(0,255,255,0.3)', lineHeight: 1.8,
      }}>
        <div>WASD / ↑↓←→  MOVE</div>
        <div>AUTO-FIRE  ●●</div>
      </div>

      {/* ── HERO CONTENT (right side, semi-transparent panel) ── */}
      <div className="relative z-10 text-right max-w-sm mx-auto px-4 animate-fade-up" style={{ marginLeft: 'auto', marginRight: '4vw' }}>
        <div style={{
          background: 'rgba(0,0,20,0.75)',
          border: '1px solid rgba(0,255,255,0.15)',
          borderRadius: '12px',
          padding: '24px 28px',
          backdropFilter: 'blur(8px)',
          boxShadow: '0 0 40px rgba(0,255,255,0.05)',
        }}>
          <div style={{ fontFamily: 'monospace', fontSize: '0.65rem', color: '#00f5ff', letterSpacing: '0.3em', textTransform: 'uppercase', marginBottom: '6px' }}>
            ▶ PLAYER ONE
          </div>

          <h1 className="text-4xl md:text-5xl font-bold mb-2 leading-tight select-none text-right">
            <span className={`block text-white drop-shadow-2xl${!typingDone ? ' text-cursor' : ''}`}>
              {typedName}
            </span>
            {showG && <span className="block shimmer-text drop-shadow-2xl">G</span>}
          </h1>

          <div className="neon-cyan-border inline-block px-3 py-1 rounded mb-4" style={{ fontFamily: 'monospace', fontSize: '0.75rem', color: '#00f5ff', background: 'rgba(0,245,255,0.05)', letterSpacing: '0.1em' }}>
            ⚡ LVL 99 DEVELOPER
          </div>

          <div className="mb-5 max-w-xs">
            <div className="flex justify-between mb-1" style={{ fontFamily: 'monospace', fontSize: '0.6rem', color: '#00f5ff', letterSpacing: '0.15em' }}>
              <span>XP ████████████████████</span><span>MAX</span>
            </div>
            <div className="h-2 rounded-full overflow-hidden neon-cyan-border" style={{ background: 'rgba(0,0,0,0.4)' }}>
              <div style={{
                height: '100%',
                width: '97%',
                background: 'linear-gradient(90deg, #00f5ff, #ff6b35, #ffd700)',
                animation: 'xpFill 1800ms ease-out forwards',
                borderRadius: '9999px',
              }} />
            </div>
          </div>

          <div className="text-base text-gray-300 mb-1">Software Developer</div>
          <div className="text-xs text-orange-400 mb-4 font-medium tracking-widest uppercase">
            Golang · Python · Spark · Java
          </div>

          <p className="text-sm text-gray-400 leading-relaxed mb-5">
            Building scalable backend systems with 1.5+ years of experience.{' '}
            <span className="text-orange-400 font-semibold">
              <LeetCodeSolvedCount username="worms_Sama" />
            </span>{' '}
            LeetCode problems solved &amp;{' '}
            <span className="text-orange-400 font-semibold">160+</span> algorithm tutorials on YouTube.
          </p>

          <div className="flex flex-col gap-2 mb-4">
            <Button
              className="bg-gradient-to-r from-orange-500 to-yellow-500 hover:from-orange-600 hover:to-yellow-600 text-white px-5 py-2 text-sm font-semibold rounded-lg transform hover:scale-105 transition-all duration-300 glow-orange-strong w-full"
              onClick={() => document.getElementById('projects').scrollIntoView({ behavior: 'smooth' })}
            >
              View My Work
            </Button>
            <Button
              variant="outline"
              className="border border-orange-500/60 text-orange-400 hover:bg-orange-500 hover:text-white px-5 py-2 text-sm font-semibold rounded-lg transform hover:scale-105 transition-all duration-300 w-full"
              onClick={() => document.getElementById('contact').scrollIntoView({ behavior: 'smooth' })}
            >
              Get In Touch
            </Button>
          </div>

          <div className="flex justify-end space-x-3">
            {[
              { icon: Github, href: 'https://github.com/Parikshith-G', label: 'GitHub' },
              { icon: Linkedin, href: 'https://linkedin.com/in/parikshith-g', label: 'LinkedIn' },
              { icon: Youtube, href: 'https://youtube.com/@AlgorithmArena', label: 'YouTube' },
            ].map(({ icon: Icon, href, label }) => (
              <a
                key={label}
                href={href}
                target="_blank"
                rel="noopener noreferrer"
                className="p-2 rounded-full bg-gray-800/50 hover:bg-gradient-to-r hover:from-orange-500 hover:to-yellow-500 text-gray-400 hover:text-white transform hover:scale-110 transition-all duration-300 border border-orange-500/20"
                aria-label={label}
              >
                <Icon size={18} />
              </a>
            ))}
          </div>

          <div className="neon-cyan-border rounded-lg p-3 mt-6 max-w-sm" style={{ background: 'rgba(0,0,20,0.7)', fontFamily: 'monospace' }}>
            <div style={{ fontSize: '0.5rem', color: '#00f5ff', letterSpacing: '0.2em', marginBottom: '8px', opacity: 0.6 }}>── STATS ──────────────────</div>
            <div className="grid grid-cols-3 gap-3 text-center">
              {[
                { label: 'LEETCODE', value: '500+' },
                { label: 'REPOS',    value: '20+' },
                { label: 'TUTORIALS',value: '160+' },
              ].map(stat => (
                <div key={stat.label}>
                  <div style={{ fontSize: '0.5rem', color: '#00f5ff', letterSpacing: '0.12em', marginBottom: '2px' }}>{stat.label}</div>
                  <div style={{ fontSize: '1.1rem', color: '#ffd700', fontWeight: 900 }}>{stat.value}</div>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>

      <div className="absolute bottom-8 left-1/2 -translate-x-1/2 animate-bounce z-10">
        <ChevronDown size={28} className="text-orange-400/60" />
      </div>
    </section>
  );
};

export default Hero;
