import React, { useState, useEffect, useRef } from 'react';
import './App.css';
import Hero from './components/Hero';
import About from './components/About';
import Experience from './components/Experience';
import Skills from './components/Skills';
import Projects from './components/Projects';
import Certifications from './components/Certifications';
import Contact from './components/Contact';
import Navigation from './components/Navigation';
import FloatingShapes from './components/FloatingShapes';

// ── CRT scanline overlay ─────────────────────────────────────────
const CRTOverlay = () => (
  <div style={{
    position: 'fixed', inset: 0, pointerEvents: 'none', zIndex: 9999,
    background: 'repeating-linear-gradient(0deg, transparent, transparent 2px, rgba(0,0,0,0.03) 2px, rgba(0,0,0,0.03) 4px)',
    opacity: 0.15,
  }} />
);

// ── Cursor trail ─────────────────────────────────────────────────
const CursorTrail = () => {
  const [dots, setDots] = useState([]);
  const prefersReduced = typeof window !== 'undefined' && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  useEffect(() => {
    if (prefersReduced) return;
    const handler = (e) => {
      setDots(prev => [...prev.slice(-7), { id: Date.now() + Math.random(), x: e.clientX, y: e.clientY }]);
    };
    document.addEventListener('mousemove', handler);
    return () => document.removeEventListener('mousemove', handler);
  }, [prefersReduced]);

  if (prefersReduced) return null;
  return (
    <>
      {dots.map(dot => (
        <div key={dot.id} style={{
          position: 'fixed', left: dot.x - 3, top: dot.y - 3,
          width: 6, height: 6, borderRadius: '50%',
          background: '#00f5ff', pointerEvents: 'none', zIndex: 9998,
          animation: 'cursorFade 600ms ease-out forwards',
        }} />
      ))}
    </>
  );
};

// ── Section unlock toast ─────────────────────────────────────────
const SECTIONS = ['about', 'experience', 'skills', 'projects', 'certifications', 'contact'];

const SectionUnlockToast = () => {
  const [toast, setToast] = useState(null);
  const unlocked = useRef(new Set());
  const prefersReduced = typeof window !== 'undefined' && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  useEffect(() => {
    const observers = SECTIONS.map(id => {
      const el = document.getElementById(id);
      if (!el) return null;
      const obs = new IntersectionObserver(([entry]) => {
        if (entry.isIntersecting && !unlocked.current.has(id)) {
          unlocked.current.add(id);
          setToast({ name: id.toUpperCase(), exiting: false });
          setTimeout(() => setToast(t => t ? { ...t, exiting: true } : null), 1200);
          setTimeout(() => setToast(null), 1500);
        }
      }, { threshold: 0.3 });
      obs.observe(el);
      return obs;
    });
    return () => observers.forEach(o => o?.disconnect());
  }, []);

  if (!toast) return null;
  return (
    <div className="neon-cyan-border glow-cyan" style={{
      position: 'fixed', top: 80, right: 16, zIndex: 9997,
      background: 'rgba(0,0,20,0.9)', padding: '10px 16px', borderRadius: '6px',
      fontFamily: 'monospace', color: '#00f5ff', fontSize: '0.75rem',
      letterSpacing: '0.15em', textTransform: 'uppercase',
      animation: prefersReduced ? 'none'
        : toast.exiting ? 'toastSlideOut 300ms ease-in forwards'
        : 'toastSlideIn 300ms ease-out forwards',
    }}>
      [ {toast.name} UNLOCKED ]
    </div>
  );
};

function App() {
  return (
    <div className="App">
      <CRTOverlay />
      <CursorTrail />
      <SectionUnlockToast />
      <FloatingShapes />
      <Navigation />
      <Hero />
      <About />
      <Experience />
      <Skills />
      <Projects />
      <Certifications />
      <Contact />
    </div>
  );
}

export default App;